// CloudIT - ImageKit Usage Collector — Load Config.
// Purpose: compute the shared run constants and hold the plan quota constants.
// All timestamps are computed at RUN TIME — never hardcode a test clock:
// publishedAt must be within ±5 minutes of ingestion (0004 stale_timestamp).
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// The usage window is MONTH-TO-DATE [first of the current UTC month, tomorrow
// 00:00 UTC) plus the 7 most recent COMPLETED UTC days (yesterday and the 6
// days before it — completed days give stable idempotency keys). The
// idempotency base is 'imagekit-mtd-' + the current UTC month. freshUntil is
// observedAt + 12h (matches the seeded 43200s freshness). The four quota
// constants are plan facts, NOT secrets — the owner fills the real plan
// quotas before activation; quota metrics are published ONLY when the
// matching constant is > 0 (a 0 placeholder never publishes a guessed quota).

const now = new Date();
const nowMs = now.getTime();
const DAY_MS = 24 * 60 * 60 * 1000;
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());

const monthStartDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const tomorrow = new Date(nowMs + DAY_MS);
const days = [];
for (let i = 1; i <= 7; i++) { // 7 completed UTC days, ending yesterday
  const start = new Date(nowMs - i * DAY_MS);
  days.push({ label: 'day-' + i, start: ymd(start), end: ymd(new Date(start.getTime() + DAY_MS)) });
}
const monthBucket = ymd(now).slice(0, 7);

return [{
  json: {
    bandwidthQuotaBytes: 0,
    storageQuotaBytes: 0,
    vpuQuota: 0,
    extensionQuota: 0,
    monthStart: monthStartDate.toISOString(),
    monthEnd: ymd(tomorrow) + 'T00:00:00.000Z',
    monthStartYmd: ymd(monthStartDate),
    monthEndYmd: ymd(tomorrow),
    monthBucket,
    days,
    observedAt: now.toISOString(),
    publishedAt: now.toISOString(),
    freshUntil: new Date(nowMs + 12 * 3600 * 1000).toISOString(),
    base: 'imagekit-mtd-' + monthBucket
  }
}];

// CloudIT - ImageKit Usage Collector — Normalize Usage.
// Purpose: turn the 8 usage responses (month-to-date + 7 daily trend) into
// metric_sample records plus the provider_connection — or, when ANY request
// failed, into the single failure provider_connection.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// - Month-to-date publishes the 5 usage metrics, the quota metrics ONLY for
//   quota constants > 0, and quota_utilization_percent
//   (round1(bandwidthBytes / bandwidthQuotaBytes * 100)) ONLY when the
//   bandwidth quota is configured AND bandwidthBytes is present.
// - Each day publishes the 5 usage metrics that response actually contains.
// - Exactly 8 GETs per run by design: the endpoint response is
//   provider-cached ~6h per account+date-range; do NOT add extra calls.
// - Any failed request -> only the failure provider_connection is published
//   (a partial window would leave misleading gaps next to full ones).
//
// WIRING NOTE: this node reads each Get Usage node once via
// $('...').first().json — safe because the chain is a single straight line
// executed exactly once (the proven Phase 6 v2 pattern: n8n HTTP nodes do
// not pass input fields through).

const config = $('Load Config').first().json;
const responses = {
  mtd: $('Get Usage Month To Date').first().json,
  d1: $('Get Usage Day 1').first().json,
  d2: $('Get Usage Day 2').first().json,
  d3: $('Get Usage Day 3').first().json,
  d4: $('Get Usage Day 4').first().json,
  d5: $('Get Usage Day 5').first().json,
  d6: $('Get Usage Day 6').first().json,
  d7: $('Get Usage Day 7').first().json
};

// --- failure inspection -----------------------------------------------------
// A failed HTTP node (onError: continueRegularOutput) yields an item whose
// json is an error object; a 200 whose body is a provider error document
// carries an error field too. Anything that is not a confirmed healthy body
// counts as a failure; the status code is best-effort (network/timeout
// failures carry none -> category provider_unavailable, state unknown).
function failureOf(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    return { failed: true, status: null, timedOut: false };
  }
  const err = item.error
    ? (typeof item.error === 'object' ? item.error : { message: String(item.error) })
    : null;
  if (err === null) return { failed: false, status: null, timedOut: false };
  const msg = String(err.message || '') + ' ' + String(err.description || '');
  const timedOut = /timed?\s*out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg) || err.code === 'ETIMEDOUT';
  let status = null;
  for (const c of [err.statusCode, err.httpCode, item.statusCode]) {
    const n = typeof c === 'string' ? parseInt(c, 10) : c;
    if (Number.isInteger(n) && n >= 100 && n <= 599) { status = n; break; }
  }
  if (status === null) {
    const m = msg.match(/\b([45][0-9]{2})\b/);
    if (m) status = parseInt(m[1], 10);
  }
  return { failed: true, status, timedOut };
}

function failureCategory(f) {
  if (f.timedOut) return 'timeout';
  if (f.status === 401) return 'authentication';
  if (f.status === 403) return 'authorization';
  if (f.status !== null && f.status >= 500) return 'http_5xx';
  return 'provider_unavailable';
}

function failureConn(provider, connectionKey, base, f, times) {
  const denied = f.status === 401 || f.status === 403;
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: denied ? 'RED' : 'AMBER',
    severity: denied ? 'critical' : 'warning',
    payload: {
      provider,
      connectionKey,
      reachable: false,
      authorizationState: denied ? 'denied' : 'unknown',
      failureCategory: failureCategory(f)
    }
  };
}

function okConn(provider, connectionKey, base, observedAt) {
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: 'GREEN',
    severity: 'none',
    payload: {
      provider,
      connectionKey,
      reachable: true,
      authorizationState: 'ok',
      lastSuccessfulAt: observedAt
    }
  };
}

let failedCall = null;
let failedKey = null;
for (const key of ['mtd', 'd1', 'd2', 'd3', 'd4', 'd5', 'd6', 'd7']) {
  const f = failureOf(responses[key]);
  if (f.failed) { failedCall = f; failedKey = key; break; }
}

if (failedCall !== null) {
  const record = failureConn('imagekit', 'usage-api', config.base, failedCall);
  return [{
    json: {
      observedAt: config.observedAt,
      publishedAt: config.publishedAt,
      freshUntil: config.freshUntil,
      records: [record],
      diagnostics: { failedCall: failedKey, status: failedCall.status }
    }
  }];
}

// --- usage field pickers -----------------------------------------------------
// VERIFY-ON-FIRST-RUN: confirm the live usage field names; snake_case
// fallbacks are included and diagnostics reports matched/missing per call.
// Any key absent from a response is OMITTED — never guessed.
function num(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v))) return Number(v);
  return null;
}
const USAGE = [
  { metricKey: 'imagekit.bandwidth_bytes',
    unit: 'bytes',
    pick: (r) => num(r.bandwidthBytes !== undefined ? r.bandwidthBytes : r.bandwidth_bytes) },
  { metricKey: 'imagekit.media_library_storage_bytes',
    unit: 'bytes',
    pick: (r) => num(r.mediaLibraryStorageBytes !== undefined ? r.mediaLibraryStorageBytes : r.media_library_storage_bytes) },
  { metricKey: 'imagekit.video_processing_units',
    unit: 'units',
    pick: (r) => num(r.videoProcessingUnitsCount !== undefined ? r.videoProcessingUnitsCount
      : (r.videoProcessingUnits !== undefined ? r.videoProcessingUnits : r.video_processing_units)) },
  { metricKey: 'imagekit.extension_units',
    unit: 'units',
    pick: (r) => num(r.extensionUnitsCount !== undefined ? r.extensionUnitsCount
      : (r.extensionUnits !== undefined ? r.extensionUnits : r.extension_units)) },
  { metricKey: 'imagekit.original_cache_storage_bytes',
    unit: 'bytes',
    pick: (r) => num(r.originalCacheStorageBytes !== undefined ? r.originalCacheStorageBytes : r.original_cache_storage_bytes) }
];

function sampleRecord(metricKey, unit, value, periodStart, periodEnd, idempotencyKey, sampledAt) {
  return {
    recordType: 'metric_sample',
    idempotencyKey,
    status: 'GREEN',
    severity: 'info',
    payload: {
      metricKey,
      sampledAt,
      valueNumber: value,
      unit,
      periodStart,
      periodEnd,
      coverage: 'full',
      dimensions: {}
    }
  };
}

const records = [];
const monthIdem = (k) => 'imagekit-mtd-' + config.monthBucket + ':' + k;
const dayIso = (d) => d + 'T00:00:00.000Z';

// --- month-to-date ------------------------------------------------------------
const mtdMatched = [];
for (const u of USAGE) {
  const value = u.pick(responses.mtd);
  if (value === null) continue;
  mtdMatched.push(u.metricKey);
  records.push(sampleRecord(u.metricKey, u.unit, value, config.monthStart, config.monthEnd,
    monthIdem(u.metricKey), config.observedAt));
}
const bandwidthBytes = USAGE[0].pick(responses.mtd);

// --- quota metrics: ONLY when the config constant is > 0 (never a guess) ------
const quotaDefs = [
  { metricKey: 'imagekit.bandwidth_quota_bytes', unit: 'bytes', value: num(config.bandwidthQuotaBytes) },
  { metricKey: 'imagekit.media_library_storage_quota_bytes', unit: 'bytes', value: num(config.storageQuotaBytes) },
  { metricKey: 'imagekit.video_processing_units_quota', unit: 'units', value: num(config.vpuQuota) },
  { metricKey: 'imagekit.extension_units_quota', unit: 'units', value: num(config.extensionQuota) }
];
const quotaMatched = [];
for (const q of quotaDefs) {
  if (q.value === null || q.value <= 0) continue; // placeholder 0 -> omitted, never a guessed quota
  quotaMatched.push(q.metricKey);
  records.push(sampleRecord(q.metricKey, q.unit, q.value, config.monthStart, config.monthEnd,
    monthIdem(q.metricKey), config.observedAt));
}
if (num(config.bandwidthQuotaBytes) > 0 && bandwidthBytes !== null) {
  const pct = Math.round((bandwidthBytes / num(config.bandwidthQuotaBytes)) * 1000) / 10;
  records.push(sampleRecord('imagekit.quota_utilization_percent', 'percent', pct,
    config.monthStart, config.monthEnd, monthIdem('imagekit.quota_utilization_percent'), config.observedAt));
}

// --- daily trend (7 completed UTC days) ---------------------------------------
const dailyResponses = [responses.d1, responses.d2, responses.d3, responses.d4, responses.d5, responses.d6, responses.d7];
const dailyMatched = [];
for (let i = 0; i < 7; i++) {
  const day = config.days[i];
  const resp = dailyResponses[i];
  let matched = 0;
  for (const u of USAGE) {
    const value = u.pick(resp);
    if (value === null) continue; // absent key -> omitted, never guessed
    matched++;
    records.push(sampleRecord(u.metricKey, u.unit, value, dayIso(day.start), dayIso(day.end),
      'imagekit-day-' + day.start + ':' + u.metricKey, config.observedAt));
  }
  dailyMatched.push({ day: day.start, matchedKeys: matched });
}

records.push(okConn('imagekit', 'usage-api', config.base, config.observedAt));

return [{
  json: {
    observedAt: config.observedAt,
    publishedAt: config.publishedAt,
    freshUntil: config.freshUntil,
    records,
    diagnostics: {
      monthToDateMatched: mtdMatched,
      quotaMatched,
      utilizationPublished: records.some((r) => r.payload.metricKey === 'imagekit.quota_utilization_percent'),
      dailyMatched
    }
  }
}];

// CloudIT - ImageKit Usage Collector — Build Records.
// Purpose: wrap the normalized records (produced by the Normalize node)
// in the strict Phase 0 section 7 evidence envelopes and attach the
// shared run timestamps from Load Config.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).
// Envelope keys are exactly the Phase 0 contract: contractVersion "1.0",
// recordType, idempotencyKey (<=160 chars, opaque, unique per record),
// environmentKey "production", sourceSystem "imagekit", observedAt,
// publishedAt, freshUntil, status, severity, correlationKey null, payload.
// Payload keys stay inside the strict allowlist of migration 0005 — any
// extra key rejects the WHOLE batch with unknown_field.

const input = $input.first().json;

const records = (Array.isArray(input.records) ? input.records : []).map((r) => ({
  contractVersion: '1.0',
  recordType: r.recordType,
  idempotencyKey: String(r.idempotencyKey),
  environmentKey: 'production',
  sourceSystem: 'imagekit',
  observedAt: input.observedAt,
  publishedAt: input.publishedAt,
  freshUntil: input.freshUntil,
  status: r.status,
  severity: r.severity,
  correlationKey: null,
  payload: r.payload
}));

return [{
  json: {
    records,
    recordCount: records.length,
    publisherKey: 'cavetta-production-n8n'
  }
}];
